#!/usr/bin/env node
// ─── Generate snake3d-bundle.js for Jest coverage ───
// Concatenates js/*.js into a single file with a _state object
// so all mutable variables are accessible via require().
// Jest CAN instrument files loaded via require().

const fs = require('fs');
const path = require('path');

const srcDir = path.join(__dirname, '..', 'js');
const files = [
  'config.js', 'state.js', 'audio.js', 'scene.js', 'snake.js',
  'apples.js', 'obstacles.js', 'particles.js', 'game.js', 'controls.js'
];

// All mutable variables that need to live in _state
const mutableVars = [
  'direction', 'score', 'highScore', 'totalGames', 'running', 'gameOver',
  'lastMoveTime', 'camSmoothX', 'camSmoothZ', 'lookSmoothX', 'lookSmoothZ',
  'headSmoothX', 'headSmoothZ', 'actx', 'musicEl', 'musicPlaying',
  'userPausedMusic', 'currentTrack', 'snake', 'apples', 'obstacles',
  'logs', 'playlist', 'scene', 'camera', 'appleGroup', 'appleMeshes',
  'obsGroup', 'obsMeshes', 'sGroup', 'headM', 'bodyMs', 'parts',
  'musicPlayerEl', 'mpPlayBtn', 'mpTrackEl', 'mpNumEl',
  'canvas', 'scoreEl', 'highscoreEl', 'overlay', 'startBtn',
  'finalScoreEl', 'hintL', 'hintR', 'gamesCountEl'
];

// Read and concatenate source files
let allCode = '';
files.forEach(f => {
  let content = fs.readFileSync(path.join(srcDir, f), 'utf8');
  // Remove module.exports blocks
  content = content.replace(/\n\/\/ ─── Module exports.*\nif\(typeof module.*?\n}/s, '');
  allCode += '// === ' + f + ' ===\n' + content + '\n\n';
});

// Create bundle with _state object
let bundled = '// ─── Snake3D Bundle for Jest Coverage ───\n';
bundled += '// Auto-generated by scripts/gen-bundle.js. DO NOT edit manually.\n';
bundled += '// Jest instruments this file via require().\n';
bundled += '// All mutable state lives in _state so tests can modify it.\n\n';

bundled += '// ─── Shared state object ───\n';
bundled += 'var _state = {};\n\n';

// Process code: replace var declarations and references with _state
let processed = allCode;

// 1. Replace var declarations: "var X = ..." -> "_state.X = ..."
mutableVars.forEach(v => {
  processed = processed.replace(
    new RegExp(`(^|;)\\s*var\\s+${v}\\s*=`, 'gm'),
    '$1\n_state.' + v + ' ='
  );
});

// 2. Replace standalone references with _state.X
// Use word boundaries and skip strings/comments
mutableVars.forEach(v => {
  const regex = new RegExp(`\\\\b${v}\\\\b`, 'g');
  processed = processed.replace(regex, (match, offset, str) => {
    const before = str.substring(0, offset);
    const lastLineStart = before.lastIndexOf('\n');
    const currentLine = before.substring(lastLineStart + 1);

    // Skip if inside a single-line comment
    if (currentLine.includes('//')) return match;

    // Skip if inside a string (count quotes before this position)
    const singleQuotes = (before.match(/'/g) || []).length;
    const doubleQuotes = (before.match(/"/g) || []).length;
    if (singleQuotes % 2 === 1 || doubleQuotes % 2 === 1) return match;

    return '_state.' + v;
  });
});

bundled += processed;

// Export everything
bundled += '// ─── Module exports for Jest ───\n';
bundled += 'module.exports = {\n';
bundled += '  _state,\n';
bundled += '  log, showErr, isOccupied, spawnOneApple, refreshApples, initApples,\n';
bundled += '  isSafeForObstacle, spawnObstacle, refreshObstacles,\n';
bundled += '  initGame, turnL, turnR, step, die, updateCam,\n';
bundled += '  buildSnake, refreshSnake, buildApples, buildObstacles,\n';
bundled += '  burst, tickParts, initAudio, tone, sfxEat, sfxTurn, sfxDie, sfxObstacle,\n';
bundled += '  initMusic, updateTrackDisplay, shufflePlaylist, pickRandomTrack,\n';
bundled += '  playTrack, toggleMusic, nextTrack, prevTrack, startMusic, stopMusic,\n';
bundled += '  gw,\n';
bundled += '  get GRID_SIZE() { return GRID_SIZE; },\n';
bundled += '  get MOVE_INTERVAL() { return MOVE_INTERVAL; },\n';
bundled += '  get TURN_ANGLE() { return TURN_ANGLE; },\n';
bundled += '  get half() { return half; },\n';
bundled += '  get NUM_APPLES() { return NUM_APPLES; },\n';
bundled += '  get MAX_OBSTACLES() { return MAX_OBSTACLES; },\n';
bundled += '  get OBSTACLE_SPAWN_EVERY() { return OBSTACLE_SPAWN_EVERY; },\n';
bundled += '  get OBSTACLE_MIN_DIST_SNAKE() { return OBSTACLE_MIN_DIST_SNAKE; },\n';
bundled += '  get OBSTACLE_MIN_DIST_EACH() { return OBSTACLE_MIN_DIST_EACH; },\n';
bundled += '  get OBSTACLE_MIN_DIST_APPLE() { return OBSTACLE_MIN_DIST_APPLE; },\n';
bundled += '};\n';

const outPath = path.join(__dirname, '..', 'tests', 'snake3d-bundle.js');
fs.writeFileSync(outPath, bundled);
console.log(`Bundle written: ${bundled.length} bytes → ${outPath}`);
